import {PANEL_ACTIONS,PANEL_SECTIONS} from './panel-permissions.js';
const NAV=[['GENEL',[['overview','◫','Genel Bakış'],['live','◎','Canlı Oyuncular'],['chat','✉','Sohbet']]],['HESAPLAR',[['users','☺','Kullanıcılar'],['permissions','⚿','Panel Yetkileri'],['clans','⚑','Klanlar'],['bans','⛔','Yasaklar'],['support','✆','Destek']]],['OYUN',[['rooms','◉','Odalar'],['rules','⚙','Oyun Kuralları'],['boost','✦','Dünya Araçları']]],['EKONOMİ',[['gold','₲','Gold ve Premium'],['crystal','✿','Kristal RTP'],['pins','✚','Pinler'],['records','♛','Rekorlar'],['names','✎','Kayıtlı İsimler']]],['İÇERİK',[['skins','◐','Skinler'],['ranks','★','Rütbeler'],['site','☰','Site ve Duyurular'],['system','▣','Sistem']]]];
export async function managementPanel(c){
 const {S,api,esc,fmt,form,input,empty}=c,[a,extra]=await Promise.all([api('management'),api('admin')]);
 const visible=key=>key==='permissions'?a.canDelegate:!PANEL_SECTIONS[key]||PANEL_SECTIONS[key].some(k=>a.permissions.includes(k)),nav=NAV.map(([name,items])=>[name,items.filter(([key])=>visible(key))]).filter(x=>x[1].length);const section=visible(S.gmSection||'overview')?(S.gmSection||'overview'):'overview',title=NAV.flatMap(x=>x[1]).find(x=>x[0]===section)?.[2]||'Genel Bakış';
 const mf=(action,fields,label)=>form(action,fields,label,'data-management="true"');
 const target=input('Hesap no','target','number','','required min="1"');
 const roomSelect='<label>Oda<select name="room">'+a.rooms.map(r=>`<option value="${esc(r.id)}">${esc(r.id)}</option>`).join('')+'</select></label>';
 const card=(heading,body)=>`<section class="gm-card"><h2>${heading}</h2>${body}</section>`;
 const table=(headers,rows)=>`<div class="gm-table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows||'<tr><td colspan="'+headers.length+'">Kayıt yok.</td></tr>'}</tbody></table></div>`;
 const metric=(label,n,sub)=>`<article class="gm-metric"><small>${label}</small><strong>${fmt(n)}</strong><span>${sub}</span></article>`;
 const users=table(['Hesap No','İsim','Gold','Bonus','Premium','Rol','Durum'],a.users.map(u=>`<tr><td><button data-gm-user="${u.id}">#${u.id}</button></td><td>${esc(u.name)}</td><td>${fmt(u.gold)}</td><td>${fmt(u.bonus)}</td><td>${u.premiumUntil>a.serverNow?'Var':'—'}</td><td>${u.role==='admin'?'Yönetici':'Oyuncu'}</td><td>${u.bannedUntil>a.serverNow?'Yasaklı':u.mutedUntil>a.serverNow?'Susturuldu':'Aktif'}</td></tr>`).join(''));
 const wallet=mf('wallet',target+'<label>Bakiye<select name="wallet"><option value="gold">Gold</option><option value="bonus">Bonus</option></select></label>'+input('Tutar (eksi değer düşürür)','amount','number','10000','required min="-100000000" max="100000000"')+input('İşlem nedeni','reason','text','','required maxlength="200"'),'Bakiyeyi güncelle');
 const premium=mf('premium',target+input('Gün (0 = kaldır)','days','number','7','required min="0" max="365"'),'Premium uygula');
 const mute=mf('mute',target+input('Saat (0 = kaldır)','hours','number','1','required min="0" max="8760"'),'Sohbet yasağını uygula');
 let body='';
 if(section==='permissions'&&a.canDelegate)body=card('Hesaba panel yetkisi ver','<p>Hesap numarası veya e-posta gir. Yalnızca seçtiğin işlemler açılır. Tüm seçimleri kaldırıp kaydetmek panel erişimini geri alır.</p>'+mf('panelAccess','<label>Hesap no / e-posta<input name="target" required maxlength="200" placeholder="123 veya oyuncu@ornek.com"></label><div class="permission-grid">'+Object.entries(a.permissionCatalog).map(([key,label])=>'<label><input type="checkbox" name="permissions" value="'+key+'">'+esc(label)+'</label>').join('')+'</div>','Yetkileri kaydet'))+card('Hesaplar ve mevcut yetkiler',a.users.filter(u=>u.id!==S.profile.id).map(u=>'<div class="list-row"><span>#'+u.id+' · '+esc(u.name)+'<small>'+u.panelPermissions.map(k=>esc(a.permissionCatalog[k])).join(', ')+'</small></span><button data-panel-user="'+u.id+'" data-panel-permissions="'+esc(JSON.stringify(u.panelPermissions))+'">Düzenle</button></div>').join(''));
 if(section==='overview')body=`<div class="gm-metrics">${metric('Bağlı oyuncu',a.stats.online,a.stats.activePlayers+' oyunda')}${metric('Açık oda',a.rooms.filter(r=>!r.closed).length,a.rooms.length+' toplam oda')}${metric('Hesap',a.stats.accounts,'kayıtlı kullanıcı')}${metric('Onay bekleyen skin',extra.uploads.filter(x=>x.status==='pending').length,'Skinler sayfası')}${metric('Açık destek',extra.tickets.filter(x=>x.status!=='Çözüldü').length,'Destek sayfası')}${metric('Toplam ödül',a.rooms.reduce((n,r)=>n+r.prize,0),'bütün odalar')}</div><div class="gm-two">${card('En kalabalık odalar','<p>Kalan süre ve ödül</p>'+table(['Oda','Oyuncu','Kalan','Ödül'],[...a.rooms].sort((x,y)=>y.players-x.players).slice(0,10).map(r=>`<tr><td>${esc(r.id)}</td><td>${r.players}</td><td>${Math.floor(r.timeLeft/60)}:${String(r.timeLeft%60).padStart(2,'0')}</td><td>${fmt(r.prize)}</td></tr>`).join(''))+'<button data-gm-section="rooms">Odalar →</button>')}${card('Son kayıt olanlar',table(['Hesap No','İsim','Gold'],a.users.slice(0,8).map(u=>`<tr><td><button data-gm-user="${u.id}">#${u.id}</button></td><td>${esc(u.name)}</td><td>${fmt(u.gold)}</td></tr>`).join(''))+'<button data-gm-section="users">Kullanıcılar →</button>')}</div>`;
 if(section==='live')body=card('Canlı Oyuncular',`<p>Oyundaki herkes: oda, skor, parça, Gold ve bağlantı durumu. 5 saniyede bir yenilenir.</p><input data-admin-player-filter type="search" placeholder="İsim, hesap no veya oda ara"><div id="management-live">${managementLive(a,c)}</div>`);
 if(section==='users')body=card('Kullanıcılar · '+a.stats.accounts,'<p>Hesap numarasına tıklayarak Gold, Premium ve yasak işlemlerini aç.</p>'+users)+`<div class="gm-two" id="gm-user-editor">${card('Gold / Bonus',wallet)}${card('Premium',premium)}</div>`;
 if(section==='gold')body=`<div class="gm-two" id="gm-user-editor">${card('Gold / Bonus düzenle',wallet)}${card('Premium yönetimi',premium)}</div>`+card('Oyun içi fiyatlar',table(['İşlem','Fiyat'],[['Bir gün Premium','22.000 Gold'],['İsim kaydetme','2.000 Gold'],['Galeri skini','Ücretsiz'],['Skin yükleme','10.000 Gold'],['ZirvePass','5.000.000 Gold']].map(x=>'<tr><td>'+x[0]+'</td><td>'+x[1]+'</td></tr>').join('')));
 if(section==='crystal'){const config=(await api('crystal/settings')).settings;body=card('Kristal Bahçesi · RTP',`<p>Yeni normal turlar ve satın alınan bonuslar için hedef RTP. Başlamış bonusların bedeli ve matematik ayarı değişmez. Ayar bütün oyunculara eşit uygulanır ve oyuncu ekranında görünür.</p>${form('crystalSettings','<input type="hidden" name="revision" value="'+config.revision+'">'+input('Hedef RTP · % (0–200)','targetRtp','number',config.targetRtp,'required min="0" max="200" step="0.01"'),'RTP ayarını kaydet','data-crystal-settings="true"')}<p>Aktif hedef: <b>%${esc(config.targetRtp)}</b> · Ayar sürümü ${config.revision}. Bu bir uzun vadeli hedeftir; kesin veya oturum başına geri ödeme garantisi değildir. 100’ün üstü hedefler ortalama dağıtılan Gold’u artırır.</p><p>Satın alma: seçilen tur bedelinin ${config.buyPriceRate} katı karşılığında 15 free spin. Normal ve satın alınan bonus farklı kalibrasyon kullanır; aynı hedefe ayarlanır. 5.000× toplam kazanç sınırı korunur. Varsayılan dışındaki hedefler ayrıca simülasyonla doğrulanmalıdır.</p>`);}
 if(section==='bans')body=`<div class="gm-two" id="gm-user-editor">${card('Süreli sohbet yasağı',mute)}${card('Hesap erişimi',form('adminBan',target+input('Saat (0 = kaldır)','hours','number','24','required min="0" max="8760"'),'Uygula'))}</div>`+card('Aktif kısıtlamalar',table(['Hesap','Oyuncu','Sohbet yasağı','Giriş yasağı'],a.users.filter(u=>u.mutedUntil>a.serverNow||u.bannedUntil>a.serverNow).map(u=>`<tr><td>#${u.id}</td><td>${esc(u.name)}</td><td>${u.mutedUntil>a.serverNow?new Date(u.mutedUntil).toLocaleString('tr-TR'):'—'}</td><td>${u.bannedUntil>a.serverNow?new Date(u.bannedUntil).toLocaleString('tr-TR'):'—'}</td></tr>`).join('')));
 if(section==='rooms')body=card('Odalar · '+a.rooms.length,'<input data-admin-room-filter type="search" placeholder="Oda ara"><div class="gm-table-scroll"><table class="data-table"><thead><tr><th>Oda</th><th>Durum</th><th>Oyuncu</th><th>İzleyici</th><th>Kalan</th><th>Ödül</th><th>Başlangıç</th><th>Boost</th></tr></thead><tbody id="management-room-rows">'+managementRoomRows(a,c)+'</tbody></table></div>')+`<div class="gm-two">${card('Yeni oda aç',mf('createRoom',input('Oda adı','room','text','','required maxlength="24"')+'<label>Tür<select name="mode"><option value="ffa">FFA</option><option value="boost">Boost</option><option value="special">Bonus Gold</option><option value="nogold">Goldsuz</option></select></label>'+input('Tur süresi · dakika','minutes','number','60','required min="1" max="1440"')+input('Başlangıç ödülü','basePrize','number','50000','required min="0" max="100000000"'),'Odayı aç'))}${card('Tur süresini ayarla','<p>Kaydettiğinde seçilen odanın kalan süresi yeniden başlar. Sonraki turlar da bu sürede oynanır.</p>'+mf('setRoomTime',roomSelect+input('Tur süresi · dakika','minutes','number','60','required min="1" max="1440"'),'Süreyi kaydet'))}${card('Gold harcaması ve oda ödülü','<p>Kapalıyken basılan Gold ödüle eklenmez. Ücretsiz MMA Gold’u ödüle eklenmez.</p>'+mf('goldToPrize',roomSelect+'<label>Gold → ödül<select name="enabled"><option value="false">Kapalı</option><option value="true">Açık</option></select></label>','Gold ayarını kaydet'))}${card('Süre ekle',mf('addTime',roomSelect+input('Eklenecek dakika','minutes','number','10','required min="1" max="1440"'),'Süre ekle'))}${card('Oda ödülüne ekle','<p>MMA ödülleri aktif oyuncu sayısına göre 50.000–250.000 Gold arasında otomatik hesaplanır.</p>'+mf('reward',roomSelect+input('Ödül · Gold','amount','number','50000','required min="1" max="100000000"')+input('Neden','reason','text','','required maxlength="200"'),'Ödül ekle'))}${card('Oda ayarları',mf('room',roomSelect+input('Başlangıç ödülü','basePrize','number','50000','required min="0" max="100000000"')+'<input type="hidden" name="extraPrize" value="0"><label>Durum<select name="closed"><option value="false">Açık</option><option value="true">Kapalı</option></select></label>','Kaydet'))}${card('Turu elle bitir',mf('finishRoom',roomSelect,'Kazananı belirle ve yeni tura geç'))}</div>`;
 if(section==='boost')body=`<div class="gm-two"><section class="gm-card" id="admin-boost"><h2>Odaya Boost ver</h2>${mf('roomBoost',roomSelect+input('Gold hız çarpanı','goldRate','number','5','required min="1" max="50"')+input('Yem aralığı · ms','feedMs','number','90','required min="50" max="1000"')+input('Bölünme aralığı · ms','splitMs','number','80','required min="50" max="1000"')+input('Dakika (0 = süresiz)','minutes','number','10','required min="0" max="10080"'),'Boost uygula')}<p>Aralık küçüldükçe hız artar. Gold çarpanı harcanan Gold ve eklenen kütleyi birlikte artırır. Aktif Boost’ta ekran kenarları sararır.</p></section>${card('Normal hıza dön',mf('roomBoost',roomSelect+'<input type="hidden" name="goldRate" value="1"><input type="hidden" name="feedMs" value="90"><input type="hidden" name="splitMs" value="80"><input type="hidden" name="minutes" value="0">','Boost kapat'))}</div>`;
 if(section==='chat'||section==='site')body=`<div class="gm-two">${card('Tüm odalara duyuru',mf('announce','<label>Duyuru<textarea name="text" required maxlength="300"></textarea></label>','Duyuruyu gönder'))}${card('Sohbet yasağı',mute)}</div>`+card('Oyuncu şikayetleri',a.reports.map(r=>`<section class="sub-card"><b>#${r.id} · #${r.reporter} → #${r.target} · ${esc(r.status)}</b><p>${esc(r.text)}</p>${mf('reportStatus','<input type="hidden" name="target" value="'+r.id+'"><label>Durum<select name="status"><option>Açık</option><option>İnceleniyor</option><option>Çözüldü</option></select></label>','Kaydet')}</section>`).join('')||'<p>Şikayet yok.</p>');
 if(section==='pins')body=card('Tek kullanımlık PIN üret',mf('pin','<label>Tür<select name="kind"><option value="gold">Gold</option><option value="premium">Premium gün</option></select></label>'+input('Miktar / gün','amount','number','10000','required min="1" max="100000000"'),'PIN oluştur')+'<p>Üretilen kod bir kez gösterilir. Kodlar sunucuda özetlenerek saklanır.</p>');
 if(section==='support')body=card('Destek talepleri',extra.tickets.map(t=>`<section class="sub-card"><small>#${t.id} · Hesap #${t.account_id} · ${esc(t.status)}</small><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p>${t.replies.map(r=>`<p>#${r.author}: ${esc(r.text)}</p>`).join('')}${form('ticketReply','<input type="hidden" name="target" value="'+t.id+'">'+input('Yanıt','value','text','','required minlength="2" maxlength="500"'),'Yanıtla')}<div>${['Açık','İnceleniyor','Çözüldü'].map(status=>`<button data-act="adminTicket" data-target="${t.id}" data-value="${status}">${status}</button>`).join(' ')}</div></section>`).join('')||'<p>Açık talep yok.</p>');
 if(section==='skins')body=card('Skin denetimi','<div class="skin-grid">'+extra.uploads.map(u=>`<article class="skin-card"><img src="/skins/${encodeURIComponent(u.id)}.webp" width="128" height="128" alt="İncelenecek skin"><small>#${u.account_id} · ${esc(u.status)}</small><button data-act="adminUpload" data-target="${esc(u.id)}" data-value="approved">Onayla</button><button data-act="adminUpload" data-target="${esc(u.id)}" data-value="rejected">Reddet</button></article>`).join('')+'</div>'+(extra.uploads.length?'':'<p>Yüklenmiş skin yok.</p>'));
 if(section==='clans'){const list=await api('clans');body=card('Klanlar',table(['Klan','İsim','Sahip','Galibiyet'],list.map(x=>`<tr><td>#${x.id}</td><td>${esc(x.name)}</td><td>#${x.owner}</td><td>${fmt(x.wins)}</td></tr>`).join('')))}
 if(section==='records'){const list=await api('records');body=card('Son Rekorlar',table(['Oda','Oyuncu','Skor','Tarih','Tekrar'],list.map(x=>`<tr><td>${esc(x.room)}</td><td>${esc(x.name)}</td><td>${fmt(x.score)}</td><td>${new Date(x.at).toLocaleString('tr-TR')}</td><td><button data-watch="${x.id}">Son 5 dakikayı izle</button></td></tr>`).join('')))}
 if(section==='names'){const list=await Promise.all(a.users.map(u=>api('profile/'+u.id)));body=card('Kayıtlı İsimler',table(['Hesap','Oyuncu','Kayıtlı isimler'],list.map(u=>`<tr><td>#${u.id}</td><td>${esc(u.name)}</td><td>${u.names.map(esc).join(', ')||'—'}</td></tr>`).join('')))}
 if(section==='ranks'){const list=await api('rankings');body=card('Rütbeler ve sıralama',table(['Sıra','Hesap','Oyuncu','Galibiyet'],list.map((u,i)=>`<tr><td>${i+1}</td><td>#${u.id}</td><td>${esc(u.name)}</td><td>${fmt(u.wins)}</td></tr>`).join('')))}
 if(section==='rules')body=card('Aktif oyun kuralları',table(['Kural','Değer'],[['Parça sınırı','25'],['Otomatik bölünme','Normal / MMA-1: 220.000 · MMA-2: 250.000 · MMA-3: 350.000 skor'],['Toplam skor sınırı','Normal / MMA-1: 5.500.000 · MMA-2: 6.250.000 · MMA-3: 8.750.000'],['Küçük Gold','10 Gold → 50 kütle'],['Büyük Gold','100 Gold → 250 kütle'],['Yem aralığı','90 ms (oda Boost ile değişir)'],['Bölünme aralığı','80 ms (oda Boost ile değişir)']].map(x=>'<tr><td>'+x[0]+'</td><td>'+x[1]+'</td></tr>').join(''))+'<button data-gm-section="boost">Odaya özel hızları düzenle →</button>');
 if(section==='system')body=card('İşlem denetimi',table(['Yönetici','İşlem','Hedef','Ayrıntı'],extra.audit.map(x=>`<tr><td>#${x.actor}</td><td>${esc(x.action)}</td><td>#${x.target}</td><td>${esc(x.detail)}</td></tr>`).join('')))+(a.canReset?card('Testi bitir · Oyunu tamamen sıfırla','<p>Bütün test verileri temizlenir. Yönetici girişin korunur. Parola ve ikinci onay gerekir; önce otomatik yedek alınır.</p>'+form('prepareReset',input('Hesap parolan','password','password','','required autocomplete="current-password"'),'Sıfırlama onayını hazırla','data-reset-prepare="true"')):'');
 const fragment=document.createElement('template');fragment.innerHTML=body;for(const form of fragment.content.querySelectorAll('form[data-action]')){const action=form.dataset.action;if(action==='panelAccess'? !a.canDelegate : PANEL_ACTIONS[action]&&!a.permissions.includes(PANEL_ACTIONS[action]))form.remove()}body=fragment.innerHTML;
 return `<div class="gm-shell"><aside class="gm-sidebar"><div class="gm-brand"><b>AM</b><div><strong>Agarm</strong><small>Yönetim Paneli</small></div></div><nav>${nav.map(([group,items])=>`<div class="gm-nav-group">${group}</div>${items.map(([id,icon,label])=>`<button data-gm-section="${id}" class="${id===section?'active':''}" aria-current="${id===section?'page':'false'}"><span>${icon}</span>${label}</button>`).join('')}`).join('')}</nav><footer><span>● Bağlı</span><a href="/" target="_blank" rel="noopener">Oyunu aç ↗</a></footer></aside><main class="gm-main"><header class="gm-heading"><div><h1>${title}</h1><p>${section==='overview'?'Sunucunun anlık durumu.':'İşlemler yönetici hesabınla uygulanır ve kayda alınır.'}</p></div><time>${new Date(a.serverNow).toLocaleTimeString('tr-TR')}</time><button data-gm-refresh="1">↻ Yenile</button></header><div class="gm-content">${body}</div></main></div>`;
}
export function managementRoomRows(a,{esc,fmt}){return a.rooms.map(r=>`<tr><td>${esc(r.id)}</td><td>${r.closed?'Kapalı':'Açık'}</td><td>${r.players}</td><td>${r.spectators||0}</td><td>${Math.floor(r.timeLeft/60)}:${String(r.timeLeft%60).padStart(2,'0')}</td><td>${fmt(r.prize)}<small>Gold → ödül: ${r.gold_to_prize?'Açık':'Kapalı'}</small></td><td>${fmt(r.base_prize)}</td><td>${r.boost&&(!r.boost.until||r.boost.until>a.serverNow)?`Gold ×${r.boost.gold} · Yem ${r.boost.feedMs} ms · Bölünme ${r.boost.splitMs} ms${r.boost.until?` · ${Math.max(0,Math.ceil((r.boost.until-a.serverNow)/60000))} dk`:" · Süresiz"}`:"Normal"}<br><button class="soft" type="button" data-room-boost="${esc(r.id)}">Boost ayarla</button></td></tr>`).join('')}
export function managementLive(a,{esc,fmt,form}){const metric=(title,n)=>`<div class="metric">${title}<strong>${fmt(n)}</strong></div>`;return `<div class="metric-row admin-metrics">${metric('Aktif oyuncu',a.stats.activePlayers)}${metric('İzleyici',a.stats.spectators)}${metric('Misafir',a.stats.guests)}${metric('Bağlantı',a.stats.online)}${metric('Dolu oda',a.stats.activeRooms)}${metric('Toplam hesap',a.stats.accounts)}</div><h3>Şu an bağlı oyuncular <small>· ${new Date(a.serverNow).toLocaleTimeString('tr-TR')}</small></h3><div class="admin-table-scroll"><table class="data-table"><thead><tr><th>HESAP</th><th>İSİM</th><th>ODA</th><th>DURUM</th><th>SKOR / REKOR</th><th>PARÇA</th><th>GOLD / BONUS</th><th>TAKIM / KLAN</th><th>PREMIUM</th><th>SON SİNYAL</th><th>İŞLEM</th></tr></thead><tbody>${a.livePlayers.map(p=>`<tr><td>${p.accountId?'#'+p.accountId:'Misafir'}</td><td>${esc(p.name)}</td><td>${esc(p.room)}</td><td>${p.spectator?'İzliyor':p.alive?'Oynuyor':'Ölü / menü'}${p.mutedUntil>a.serverNow?`<small class="danger-text">Sohbet banı · ${Math.ceil((p.mutedUntil-a.serverNow)/3600000)} saat kaldı</small>`:''}</td><td>${fmt(p.score)} / ${fmt(p.max)}</td><td>${p.cells}</td><td>${fmt(p.gold)} / ${fmt(p.bonus)}</td><td>${esc(p.team||'—')} / ${p.clanId?'#'+p.clanId:'—'}</td><td>${p.premium?'Var':'Yok'}</td><td>${Math.floor(p.lastPingAgoMs/1000)} sn önce</td><td>${p.accountId?form('score','<input type="hidden" name="target" value="'+p.accountId+'"><label>Skor<input name="amount" type="number" value="10000" required min="1" max="'+(p.massLimit||5500000)+'"></label><input name="reason" aria-label="İşlem nedeni" placeholder="İşlem nedeni" required maxlength="200">','Skor ekle','data-management="true"'):''}${p.accountId?form('mute','<input type="hidden" name="target" value="'+p.accountId+'"><label>Saat (0 = kaldır)<input aria-label="Sohbet banı süresi" type="number" name="hours" value="1" min="0" max="8760" required></label>','Sohbet banı','data-management="true"'):''}${form('kick','<input type="hidden" name="connection" value="'+esc(p.connection)+'">','Oyuncuyu at','data-management="true"')}</td></tr>`).join('')||'<tr><td colspan="11">Bağlı oyuncu yok.</td></tr>'}</tbody></table></div>`}
